import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.CWWEQfK7.js";const c=JSON.parse('{"title":"Ershu 能解决哪些问题","description":"从企业 AI 编程、内部 Wiki、跨仓库改动和团队协作四个角度判断 Ershu 是否适合你的项目。","frontmatter":{"page_id":"overview-use-cases","title":"Ershu 能解决哪些问题","description":"从企业 AI 编程、内部 Wiki、跨仓库改动和团队协作四个角度判断 Ershu 是否适合你的项目。"},"headers":[],"relativePath":"overview/use-cases.md","filePath":"overview/use-cases.md","lastUpdated":1786627803000}'),l={name:"overview/use-cases.md"};function h(d,a,o,s,n,u){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="ershu-能解决哪些问题" tabindex="-1">Ershu 能解决哪些问题 <a class="header-anchor" href="#ershu-能解决哪些问题" aria-label="Permalink to &quot;Ershu 能解决哪些问题&quot;">​</a></h1><p>Ershu 先把项目上下文整理好，再交给人和 AI 使用。下面这些场景都可以从现有功能直接验证，不需要先相信一个抽象承诺。</p><h2 id="ai-编程-减少每个任务的上下文重建" tabindex="-1">AI 编程：减少每个任务的上下文重建 <a class="header-anchor" href="#ai-编程-减少每个任务的上下文重建" aria-label="Permalink to &quot;AI 编程：减少每个任务的上下文重建&quot;">​</a></h2><p>开发智能体通常会写代码，却缺少项目约定。它可能只看到当前仓库，不知道另一个服务已经定义了接口；也可能读到一篇旧文档，却看不出它对应哪个提交。</p><p>Ershu 给 AI 客户端提供一组项目范围的只读 MCP 工具。智能体可以先发现项目和仓库，再按需要读取：</p><ul><li>项目概览和 Wiki 章节；</li><li>仓库目录、代码索引和有限范围的源码；</li><li>项目搜索、知识关系、变更影响面和静态运行路径；</li><li>公开接口、消费者契约和数据结构；</li><li>提交、新鲜度、覆盖范围、降级和截断信息。</li></ul><p>这不会保证 AI 一定写对代码，但会让它更早看到项目边界，也让评审者更容易追问“这个结论来自哪里”。</p><h3 id="一个更稳妥的工作顺序" tabindex="-1">一个更稳妥的工作顺序 <a class="header-anchor" href="#一个更稳妥的工作顺序" aria-label="Permalink to &quot;一个更稳妥的工作顺序&quot;">​</a></h3><ol><li>先让智能体用 MCP 找到项目、仓库和当前提交。</li><li>读取项目概览和相关 Wiki 章节，建立方向。</li><li>用搜索、关系或接口契约缩小候选范围。</li><li>最后读取关键源码，并在本地执行真实测试。</li></ol><p>这种顺序比一开始把大量文件塞进上下文更容易控制，也能减少与当前任务无关的内容。</p><h2 id="内部-wiki-让代码知识服务整个团队" tabindex="-1">内部 Wiki：让代码知识服务整个团队 <a class="header-anchor" href="#内部-wiki-让代码知识服务整个团队" aria-label="Permalink to &quot;内部 Wiki：让代码知识服务整个团队&quot;">​</a></h2><p>代码库里的知识不只影响写代码的人。一个功能为什么失败、一个字段从哪里来、某个接口由谁消费，都会影响测试、产品、支持、交付和架构决策。</p><table tabindex="0"><thead><tr><th>角色</th><th>Wiki 能提供的起点</th><th>仍需回到哪里确认</th></tr></thead><tbody><tr><td>新开发者</td><td>项目概览、仓库职责、入口和主要流程</td><td>当前源码、测试和维护者补充的历史背景</td></tr><tr><td>维护者</td><td>配置、模块关系、接口说明和源码引用</td><td>实际分支、提交和变更内容</td></tr><tr><td>测试人员</td><td>接口、数据结构、消息通道和异常流程</td><td>可运行环境、测试数据和验收规则</td></tr><tr><td>产品与支持</td><td>功能由哪些模块组成，相关文档和可检索术语</td><td>业务规则、客户约定和发布说明</td></tr><tr><td>架构与安全人员</td><td>仓库关系、公开入口、依赖候选和访问边界</td><td>动态运行证据、安全测试和部署配置</td></tr></tbody></table><p>Wiki 页面支持 Markdown、Mermaid 图、目录导航和来源预览。文档按仓库与类别组织，一个项目可以同时包含多个仓库。它适合做共同入口，不应被当成源码的替代品。</p><h2 id="跨仓库改动-先找影响范围-再动手" tabindex="-1">跨仓库改动：先找影响范围，再动手 <a class="header-anchor" href="#跨仓库改动-先找影响范围-再动手" aria-label="Permalink to &quot;跨仓库改动：先找影响范围，再动手&quot;">​</a></h2><p>很多企业项目按仓库分工，却按产品交付。一次改动可能从前端请求开始，经过 API、消息、服务和数据库结构，最后影响另一个团队维护的消费者。</p><p>Ershu 可以把这些线索放在同一个项目里：</p><ul><li>知识图谱展示仓库、目录、符号和依赖关系；</li><li>变更面查询从一个路径或符号寻找直接与相关候选；</li><li>静态运行路径沿调用和关系数据整理可能经过的步骤；</li><li>接口契约把提供方、消费者、公开接口和数据结构单独列出来；</li><li>跨仓库搜索允许一次查询覆盖整个项目，也可以收窄到一个仓库。</li></ul><p>这些结果用于缩小检查范围。动态调用、反射、运行时配置和外部系统仍可能不在静态结果中，因此上线前仍需测试和人工评审。</p><h2 id="交接与遗留系统-把-问某个人-变成-先查项目" tabindex="-1">交接与遗留系统：把“问某个人”变成“先查项目” <a class="header-anchor" href="#交接与遗留系统-把-问某个人-变成-先查项目" aria-label="Permalink to &quot;交接与遗留系统：把“问某个人”变成“先查项目”&quot;">​</a></h2><p>当关键维护者离开，或者团队接手一个长期缺少文档的系统时，手工补 Wiki 往往要先完成一遍耗时的源码调研。Ershu 可以先从当前仓库建立基线，给后续访谈和补充说明一个共同目录。</p><p>更实际的用法是：</p><ol><li>把共同交付的仓库放入一个项目。</li><li>完成第一次全项目分析。</li><li>让原维护者检查关键文档和关系，并补充代码中无法表达的原因与限制。</li><li>把团队经常问的问题整理成 Wiki 阅读路径或 MCP 使用提示。</li><li>用后续运行和仓库触发保持事实层更新。</li></ol><p>Ershu 能从代码重建“现在是什么”，但无法凭空恢复没有留在代码、提交或文档中的业务历史。</p><h2 id="容易被忽略的几项能力" tabindex="-1">容易被忽略的几项能力 <a class="header-anchor" href="#容易被忽略的几项能力" aria-label="Permalink to &quot;容易被忽略的几项能力&quot;">​</a></h2><h3 id="_1-接口契约可以单独查询" tabindex="-1">1. 接口契约可以单独查询 <a class="header-anchor" href="#_1-接口契约可以单独查询" aria-label="Permalink to &quot;1. 接口契约可以单独查询&quot;">​</a></h3><p>除了搜索代码，Ershu 还会整理 OpenAPI、GraphQL、Protobuf、Thrift、AsyncAPI、消息通道、数据库结构、生成客户端和部分框架路由等事实。MCP 客户端可以查询消费者契约、公开接口、结构定义和契约差异。</p><h3 id="_2-结果会说明自己是否完整" tabindex="-1">2. 结果会说明自己是否完整 <a class="header-anchor" href="#_2-结果会说明自己是否完整" aria-label="Permalink to &quot;2. 结果会说明自己是否完整&quot;">​</a></h3><p>搜索和关系查询会返回实际模式、降级原因、覆盖范围、状态和截断提示。文档和仓库资料也带提交与新鲜度。空结果不再自动等于“项目里没有”，它也可能表示资料尚未生成或当前查询受限。</p><h3 id="_3-分析过程可以追踪" tabindex="-1">3. 分析过程可以追踪 <a class="header-anchor" href="#_3-分析过程可以追踪" aria-label="Permalink to &quot;3. 分析过程可以追踪&quot;">​</a></h3><p>运行详情保留阶段、时间线、工具结果、警告和模型用量。任务中断后可以依靠持久状态继续处理，关闭浏览器不会取消后台任务。</p><h3 id="_4-团队访问与-ai-访问分开管理" tabindex="-1">4. 团队访问与 AI 访问分开管理 <a class="header-anchor" href="#_4-团队访问与-ai-访问分开管理" aria-label="Permalink to &quot;4. 团队访问与 AI 访问分开管理&quot;">​</a></h3><p>网页按用户、项目成员和额外授权控制访问。MCP 密钥属于用户，可以限制到一个或多个项目并设置过期时间。密钥不会扩大创建者原本的项目权限。</p><h3 id="_5-模型并不写死在部署文件里" tabindex="-1">5. 模型并不写死在部署文件里 <a class="header-anchor" href="#_5-模型并不写死在部署文件里" aria-label="Permalink to &quot;5. 模型并不写死在部署文件里&quot;">​</a></h3><p>管理员通过网页配置语言模型、向量模型和重排模型通道。可以按环境选择 OpenAI、OpenAI 兼容、DeepSeek 或 Anthropic 类型的提供方。代码是否发往外部服务，取决于团队实际启用的通道。</p><h2 id="哪些情况下暂时不值得部署" tabindex="-1">哪些情况下暂时不值得部署 <a class="header-anchor" href="#哪些情况下暂时不值得部署" aria-label="Permalink to &quot;哪些情况下暂时不值得部署&quot;">​</a></h2><ul><li>只有一个很小、边界清楚、几个人都熟悉的仓库；</li><li>团队只需要一次性的本地代码搜索，不需要共享结果；</li><li>无法提供 PostgreSQL、Milvus、Worker 和模型通道等运行条件；</li><li>期望工具自动证明所有运行时行为，或者替代测试与评审；</li><li>不愿意为私有代码明确模型、网络、凭据和仓库路径的信任边界。</li></ul><p>如果前面的场景与你的团队相符，下一步是在一个非关键项目上完成<a href="/guide/quick-start">单机快速部署</a>，再用一个真实的跨仓库问题验证结果。</p>',38)])])}const b=i(l,[["render",h]]);export{c as __pageData,b as default};
